/**
 * Request logging shared by the admin API handlers (amfa-442 W3-1, D1).
 * No imports on purpose: unit-testable without the AWS SDK.
 * CommonJS on purpose: index.cjs (the entry the esbuild CJS bundles resolve)
 * must export it synchronously, since handlers call it without await.
 */

/**
 * Log the request summary and nothing else from the event: the full API
 * Gateway event carries the bearer token, cookies and the request body.
 *
 * @param {{info: Function}} logger - admin-auth createLogger instance (or console)
 * @param {Object} event - API Gateway HTTP API v2 event (REST v1 fields tolerated)
 * @param {string} [tenantId] - verified tenant id, when the caller already has it
 */
function logRequest(logger, event, tenantId) {
    const ctx = event?.requestContext || {};
    const entry = {
        method: ctx.http?.method ?? ctx.httpMethod,
        path: event?.rawPath ?? ctx.routeKey ?? event?.path,
        requestId: ctx.requestId,
        sourceIp: ctx.http?.sourceIp ?? ctx.identity?.sourceIp,
        tenantId: tenantId ?? ctx.authorizer?.lambda?.tenantId,
    };
    Object.keys(entry).forEach((k) => { if (entry[k] === undefined) delete entry[k]; });
    logger.info('request', entry);
}

module.exports = { logRequest };
